#include <stdio.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 10

typedef struct {
    int num;
    char color;
} Card;

// 记录题解
int ans = 0;

// 记录输入的卡牌信息
Card cards[MAX_SIZE];
int cards_size = 0;

// 回溯求解所有出牌情况
void dfs(int used[], Card* last, int count);

int main() {
    while (scanf("%d", &cards[cards_size].num)) {
        cards_size++;
        if (getchar() != ' ') break;
    }

    for (int i = 0; i < cards_size; i++) {
        cards[i].color = (char) getchar();
        getchar();
    }

    // 记录哪些牌使用过了
    int used[MAX_SIZE] = {0};
    dfs(used, NULL, 0);

    printf("%d\n", ans);

    return 0;
}

void dfs(int used[], Card* last, int count) {
    ans = MAX(ans, count);

    for(int i=0; i<cards_size; i++) {
        // 如果当前牌已经使用过，则不能出牌
        if(used[i]) continue;

        // 当前牌
        Card cur = cards[i];

        // 如果 和上一张牌的数字不同，且和上一张牌的颜色也不同，则不能出牌
        if(last != NULL && last->num != cur.num && last->color != cur.color) continue;

        used[i] = 1;
        dfs(used, &cur, count + 1);
        used[i] = 0;
    }
}
